function handleRoomSelect(e: React.ChangeEvent<HTMLSelectElement>) {
  const val = e.target.value;
  router.push(val === NEW_ID ? "/admin/rooms" : `/admin/rooms?id=${val}`);
}

const NEW_ID = "__new__";

