export async function toggleRoomActive(formData: FormData) {
  await requireAdmin();
  await serviceClient()
    .from("rooms")
    .update({ active: str(formData, "active") === "true" })
    .eq("id", str(formData, "id"));
  revalidatePath("/admin/rooms");
  revalidatePath("/", "layout");
}

export async function deleteRoom(formData: FormData) {
  await requireAdmin();
  const id = str(formData, "id");
  const db = serviceClient();
  // A room that has bookings can't be removed without losing history: hide it instead.
  const { count } = await db.from("bookings").select("id", { count: "exact", head: true }).eq("room_id", id);
  if (count && count > 0) {
    await db.from("rooms").update({ active: false }).eq("id", id);
    revalidatePath("/admin/rooms");
    redirect("/admin/rooms?hidden=1");
  }
  await db.from("rooms").delete().eq("id", id);
  revalidatePath("/admin/rooms");
  revalidatePath("/", "layout");
  redirect("/admin/rooms?deleted=1");
}
